import { Button, Container } from "reactstrap";
import styles from "./styles.module.scss";
import useSWR from "swr";
import courseService, { CourseType } from "src/services/courseService";
import HeaderAuth from "src/components/common/headerAuth";
import Link from "next/link";
import PageSpinner from "src/components/common/spinner";


export default function FeaturedSession(){
    const {data, error} = useSWR("/featured", courseService.getFeaturedCourses);
    

    if (error) return <p>Erro ao carregar cursos.</p>;

    if(!data) {return <PageSpinner />};

    return(
        <>
            <HeaderAuth />
            {data.data.map((course: CourseType) => (
                <div 
                style={{
                    backgroundImage: `linear-gradient(to bottom, #6666661a, #151515), 
                    url(${process.env.NEXT_PUBLIC_BASEURL}/${course.thumbnailUrl})`,
                    backgroundSize: "cover",
                    backgroundPosition: "center",
                    height: "480px"
                }} 
                    key={course.id}
                    >
                    
                    <Container className="pt-4">
                        <p className={styles.title}>{course.name}</p>
                        <p className={styles.description}>{course.synopsis}</p>
                        <Link href={`/courses/${course.id}`} className={styles.linkText}>
                            <Button outline color="light" className={styles.button}>
                                ACESSE AGORA!
                                <img src="/buttonPlay.svg" alt="buttonImg" className={styles.buttonImg} />
                            </Button>
                        </Link>
                    </Container>
                </div>
            ))[0]}
        </>
    )

    


}

import useSWR from "swr";
import categoriesService, { CategoryType } from "src/services/categoriesService";
import styles from "../../../../styles/slideCategory.module.scss";
import ListCategoriesSlide from "../homeAuth/listCategoriesSlide";

export default function ListCategories(){
    const {data, error } = useSWR(
        "/categories", 
        categoriesService.getCategories
    );

    // console.log("CATEGORIES:", data);

    if(error) return error;
    if(!data){
        return(
            <>
                <p>Loading...</p>
            </>
        );
    }

    return(
        <>
            {data?.categories.map((category: CategoryType) => (
                <ListCategoriesSlide 
                    key={category.id} 
                    categoryId={category.id} 
                    categoryName={category.name} 
                />
            ))}
        </>
    );
}

import { useEffect, useState } from "react";
import styles from "../../../../styles/profile.module.scss";
import { Button, Form, FormGroup, Input, Label } from "reactstrap";
import { profileService } from "src/services/profileService";
import ToastComponent from "src/components/common/toast";
import { useRouter } from "next/router";

export default function UserForm(){
    const router = useRouter();
    const [color, setColor] = useState("");
    const [toastIsOpen, setToastIsOpen] = useState(false);
    const [errorMessage, setErrorMessage] = useState("");

    const [firstName, setFirstName] = useState("");
    const [lastName, setLastName] = useState("");
    const [phone, setPhone] = useState("");
    const [email, setEmail] = useState("");
    const [initialEmail, setInitialEmail] = useState(email);
    const [createdAt, setCreatedAt] = useState("");
    const date = new Date(createdAt);
    const month = date.toLocaleDateString("default", { month: "long" });


    useEffect(() => {
        profileService.fetchCurrent().then((user) => {
            setFirstName(user.firstName);
            setLastName(user.lastName);
            setPhone(user.phone);
            setEmail(user.email);
            setInitialEmail(user.email);
            setCreatedAt(user.createdAt);
        })
    }, []);

    const handleUserUpdate = async (event: React.SyntheticEvent<HTMLFormElement>) => {
        event.preventDefault();

        const res = await profileService.userUpdate({
            firstName, 
            lastName, 
            phone, 
            email, 
            createdAt
        });

        if(res === 200) {
            setToastIsOpen(true);
            setColor("bg-success");
            setErrorMessage("Perfil atualizado com sucesso!");
            setTimeout(() => setToastIsOpen(false), 1000 * 3);
            if(initialEmail !== email) {
                sessionStorage.clear();
                router.push("/");
            }
        } else  {
            setToastIsOpen(true);
            setColor("bg-danger");
            setErrorMessage("Voc├¬ n├úo pode mudar para esse email!");
            setTimeout(() => setToastIsOpen(false), 1000 * 3);
        }   

    }



    return(
        <>
            <Form className={styles.form} onSubmit={handleUserUpdate}>
                <div className={styles.formName}>
                    <p className={styles.nameAbbreviation}>
                        {firstName.charAt(0).toUpperCase()}{lastName.charAt(0).toUpperCase()}
                    </p>
                    <p className={styles.userName}>{firstName} {lastName}</p>
                </div>
                <div className={styles.memberTime}>
                    <img src="/profile/iconUserAccount.svg" alt="iconProfile" className={styles.memberTimeImg}/>
                    <p className={styles.memberTimeText}>
                        Membro desde {month} de {date.getFullYear()}.
                    </p>
                </div>
                <hr />
                <div className={styles.inputFlexDiv}>
                    <FormGroup>
                        <Label for="firstName">
                            NOME
                        </Label>
                        <Input 
                            name = "firstName"
                            type = "text"
                            id = "firstName"
                            placeholder = "qual ├® o seu primeiro nome?"
                            required
                            maxLength={20}
                            className={styles.inputFlex}
                            value={firstName}
                            onChange={(event) => setFirstName(event.target.value)}
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="lastName">
                            SOBRENOME
                        </Label>
                        <Input 
                            name = "lastName"
                            type = "text"
                            id = "lastName"
                            placeholder = "qual ├® o seu sobrenome?"
                            required
                            maxLength={20}
                            className={styles.inputFlex}
                            value={lastName}
                            onChange={(event) => setLastName(event.target.value)}
                        />
                    </FormGroup>
                </div>
                <div className={styles.inputNormalDiv}>
                    <FormGroup>
                        <Label for="phone">
                            WHATSAPP / TELEGRAM
                        </Label>
                        <Input 
                            name = "phone"
                            type = "tel"
                            id = "phone"
                            placeholder = "(XX) XXXXX-XXXX"
                            required
                            maxLength={20}
                            className={styles.inputFlex}
                            value={phone}
                            onChange={(event) => setPhone(event.target.value)}
                        />
                    </FormGroup>
                    <FormGroup>
                        <Label for="email">
                            E-MAIL
                        </Label>
                        <Input 
                            name = "email"
                            type = "email"
                            id = "email"
                            placeholder = "email@exemplo.com"
                            required
                            maxLength={20}
                            className={styles.input}
                            value={email}
                            onChange={(event) => setEmail(event.target.value)}
                        />
                    </FormGroup>
                    <Button className={styles.formBtn} outline type="submit">
                        Salvar Altera├º├Áes
                    </Button>
                </div>
            </Form>
            <ToastComponent color={color} isOpen={toastIsOpen} message={errorMessage} />
        </>
    )
}

