import { useEffect, useState } from "react";
import styles from "../../styles/registerLogin.module.scss"
import Head from "next/head";
import { Button, Container, Form, FormGroup, Input, Label } from "reactstrap";
import Footer from "src/components/common/footer";
import HeaderGeneric from "src/components/common/headerGeneric";
import { useRouter } from "next/router";
import ToastComponent from "src/components/common/toast";
import authService from "src/services/authService";

const Login = function () {
    const router = useRouter();
    const[toastColor, setToastColor] = useState("danger")
    const[toastIsOpen, setToastIsOpen] = useState(false);
    const[toastMessage, setToastMessage] = useState("");

    useEffect(() => {
        if(sessionStorage.getItem("onebitflix-token")){
            router.push("/home");
        }
    }, []);
    

    useEffect(() => {
        const registerSuccess = router.query.registered;
        if(registerSuccess === "true") {
            setToastColor("bg-success")
            setToastIsOpen(true);
            setTimeout(() => {
                setToastIsOpen(false)
            }, 1000 * 5);
            setToastMessage("Cadastro feito com sucesso!")
        }
    }, [router.query]);

    const handleLogin = async (event: React.SyntheticEvent<HTMLFormElement>) => {
        event.preventDefault();

        const formData = new FormData(event.currentTarget);
        const email = formData.get("email")!.toString();
        const password = formData.get("password")!.toString();
        const params = {email, password};

        const { status } = await authService.login(params);

        if(status === 200) {
            router.push("/home")
        } else {
            setToastColor("bg-danger")
            setToastIsOpen(true);
            setTimeout(() => {
                setToastIsOpen(false)
            }, 1000 * 5);
            setToastMessage("Falha no login")
        }
    }




  return (
    <>
      <Head>
        <title>Onebitflix - Login</title>
        <link rel="shortcut icon" href="/favicon.svg" type="image/x-icon" />
      </Head>
      <main className={styles.main}>
        <HeaderGeneric
          logoUrl="/"
          btnUrl="/register"
          btnContent="Quero me cadastrar"
        />
        <Container className="pi-5">
        <p className={styles.formTitle}>Bem vindo(a) de volta!</p>
        <Form className={styles.form} onSubmit={handleLogin}>
          <p className="text-center">
            <strong>Bem-vindo(a) ao Onebitflix!</strong>
          </p>
          <FormGroup>
            <Label for="email" className={styles.label}>
              E-MAIL
            </Label>
            <Input
              id="email"
              name="email"
              type="email"
              placeholder="Qual o seu e-mail?"
              required
              className={styles.input}
            />
          </FormGroup>

          <FormGroup>
            <Label for="password" className={styles.label}>
              E-MAIL
            </Label>
            <Input
              id="password"
              name="password"
              type="password"
              placeholder="Senha"
              required
              className={styles.input}
            />
          </FormGroup>
          <Button type="submit" outline className={styles.formBtn}>
            ENTRAR
          </Button>
        </Form>
         <ToastComponent 
            color={toastColor}
            isOpen={toastIsOpen} 
            message={toastMessage}
            />
      </Container>
      <Footer />
      </main>      
    </>
  );
};

